WITH base AS (SELECT * FROM stores WHERE city = 'Berlin'), StoresStats AS (SELECT DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, SUM(CASE WHEN city = 'Bangkok' THEN sqft ELSE 0 END) AS bangkok_sqft, SORT_ARRAY(COLLECT_SET(city)) AS city_list FROM base GROUP BY DATE_FORMAT(opened_date, 'yyyy-MM')) SELECT opened_month, bangkok_sqft, city_list FROM StoresStats WHERE bangkok_sqft > 57 ORDER BY 2, opened_month DESC;
